import{_ as s,C as o,o as e,c as d,j as i,a as r,E as l,a3 as n}from"./chunks/framework.C6R8kWFE.js";const I=JSON.parse('{"title":"9-dars (Mentor). Wireframe loyihasini yakunlash, annotatsiyalar va Figmaga eksport","description":"","frontmatter":{"title":"9-dars (Mentor). Wireframe loyihasini yakunlash, annotatsiyalar va Figmaga eksport","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (UX/UI)","link":"/mentor/9-sinf/"},"week":{"n":3,"link":"/mentor/9-sinf/hafta-03/"},"g":9,"title":"Wireframe loyihasini yakunlash, annotatsiyalar va Figmaga eksport","lead":"Izohli simli ramkalar (Annotated wireframes), PNG/SVG/PDF eksport va Figmada UI dizayn uchun referens qatlamini sozlash.","slide":"/slaydlar/9-sinf/hafta-03/dars-3.html","test":"/slaydlar/9-sinf/hafta-03/dars-3-test.html","student_link":"/9-sinf/hafta-03/dars-3","tabs":[{"g":7,"link":"/mentor/9-sinf/hafta-03/dars-1","current":false},{"g":8,"link":"/mentor/9-sinf/hafta-03/dars-2","current":false},{"g":9,"link":"/mentor/9-sinf/hafta-03/dars-3","current":true}],"prev":{"g":8,"title":"Foydalanuvchi formalari, kiritish maydonlari va xatoliklar dizayni (Form Wireframing)","link":"/mentor/9-sinf/hafta-03/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf/hafta-03/dars-3.md","filePath":"mentor/9-sinf/hafta-03/dars-3.md"}'),m={name:"mentor/9-sinf/hafta-03/dars-3.md"},h={class:"blk"},g={id:"_1-dars-rejasi",tabindex:"-1"},k={class:"blk"},u={id:"_2-dars-konspekti",tabindex:"-1"},f={class:"blk"},y={id:"_3-amaliy-mashg-ulot",tabindex:"-1"},p={class:"blk"},b={id:"_4-tezkor-savollar-checklist",tabindex:"-1"};function c(q,a,v,z,_,x){const t=o("Icon");return e(),d("div",null,[a[12]||(a[12]=i("p",null,[i("strong",null,"Hafta:"),r(" 3 · "),i("strong",null,"Davomiyligi:"),r(" 80 daqiqa · "),i("strong",null,"Turi:"),r(" nazariya + dizayn amaliyoti · "),i("strong",null,"I-bob"),r(", 9-dars")],-1)),i("div",h,[i("h2",g,[l(t,{name:"file-text"}),a[0]||(a[0]=r(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=n('<p><strong>Maqsad:</strong> o&#39;quvchilarda «Online books / E-kutubxona» veb-ilovasining to&#39;liq wireframe loyihasini (bosh sahifa, katalog/qidiruv, kitob tafsilotlari, ro&#39;yxatdan o&#39;tish) mantiqiy yakunlash, dasturchilar va jamoa uchun izohli simli ramkalar (Annotated wireframes) yozish, loyihani PNG, SVG va PDF formatlarida eksport qilish hamda uni Figma dasturiga UI dizayn uchun asosiy referens (reference layer) sifatida import qilish ko&#39;nikmalarini shakllantirish.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Izohli wireframe (Annotated wireframe) nima ekanini va undagi eslatmalar (Notes/Specifications) qanday tuzilishini biladi.</li><li>«E-kutubxona» veb-saytining barcha 4 ta asosiy ekranini yagona tizimga birlashtira oladi.</li><li>Wireframe loyihasini Axure RP yoki Balsamiq dasturidan PNG, SVG va PDF formatlarida to&#39;g&#39;ri eksport qiladi.</li><li>Eksport qilingan wireframeni Figma dasturiga import qilib, yangi Frame va Layerlar ustida UI dizaynga tayyorlaydi.</li><li>I-bobning «Wireframe loyihalash» bo&#39;limi bo&#39;yicha to&#39;liq amaliy portfolio ishiga ega bo&#39;ladi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Takrorlash va kirish</td><td>O&#39;tgan darslarni takrorlash (Interactions, Formalar). Muammo: «Wireframe chizildi, lekin dasturchi yoki UI dizayner unga qarab qanday ishlashini qayerdan biladi?»</td></tr><tr><td>10–30 daq</td><td>Yangi mavzu: Nazariya</td><td>Izohli wireframe (Annotations), eksport formatlari (PNG, SVG, PDF) va Figmaga ko&#39;chirish arxitekturasi</td></tr><tr><td>30–35 daq</td><td>Tanaffus</td><td>Harakatli tanaffus</td></tr><tr><td>35–65 daq</td><td>Amaliy mashg&#39;ulot</td><td>«E-kutubxona» loyihasining to&#39;liq ekranlariga annotatsiyalar qo&#39;yish, PNG/SVG eksport qilish va Figma ish maydoniga referens sifatida yuklash</td></tr><tr><td>65–75 daq</td><td>Tezkor nazorat</td><td>5 ta savol-javob va loyihalar himoyasi</td></tr><tr><td>75–80 daq</td><td>Xulosa va uyga vazifa</td><td>I-bob 1.3-mavzusi xulosasi va haftalik vazifalar</td></tr></tbody></table><hr>',5))]),i("div",k,[i("h2",u,[l(t,{name:"file-text"}),a[3]||(a[3]=r(" 2. Dars konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars konspekti"'},"​",-1))]),a[5]||(a[5]=n(`<h3 id="_2-1-izohli-simli-ramkalar-annotated-wireframes" tabindex="-1">2.1. Izohli simli ramkalar (Annotated Wireframes) <a class="header-anchor" href="#_2-1-izohli-simli-ramkalar-annotated-wireframes" aria-label="Permalink to &quot;2.1. Izohli simli ramkalar (Annotated Wireframes)&quot;">​</a></h3><p>Faqatgina vizual bloklarning o&#39;zi dasturchi yoki jamoaga har doim ham hamma narsani tushuntira olmaydi. Shu sababli professional dizaynda <strong>Annotated Wireframe (Izohli simli ramka)</strong> qo&#39;llaniladi.</p><p>Annotatsiya — bu wireframe yonida joylashgan raqamlangan eslatmalar bo&#39;lib, quyidagilarni aniqlashtiradi:</p><ol><li><strong>Funksional qoidalar:</strong> «Ushbu tugma bosilganda foydalanuvchi tizimga kirgan bo&#39;lsa, yuklab olish boshlansin, kirmagan bo&#39;lsa login oynasi ochilsin».</li><li><strong>Cheklovlar va validatsiya:</strong> «Qidiruv maydoniga kamida 3 ta harf kiritilgandan so&#39;ng avtomatik takliflar (autocomplete) chiqsin».</li><li><strong>Resurslar va ma&#39;lumotlar:</strong> «Bu blokdagi kitoblar bazaning <code>top_rated</code> jadvalidan tortib olinadi».</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>+-----------------------------------------------------------+</span></span>
<span class="line"><span>| [ Wireframe Ekrani ]          | [ Annotatsiyalar ]        |</span></span>
<span class="line"><span>|  (1) [ Qidiruv maydoni ]      | (1) Min 3 ta belgi        |</span></span>
<span class="line"><span>|  (2) [ Banner slayder  ]      | (2) Har 5 sek.da aylanadi |</span></span>
<span class="line"><span>|  (3) [ Kitob kartasi   ]      | (3) Bosilganda details    |</span></span>
<span class="line"><span>+-----------------------------------------------------------+</span></span></code></pre></div><h3 id="_2-2-eksport-formatlari-va-ularning-qo-llanilishi" tabindex="-1">2.2. Eksport formatlari va ularning qo&#39;llanilishi <a class="header-anchor" href="#_2-2-eksport-formatlari-va-ularning-qo-llanilishi" aria-label="Permalink to &quot;2.2. Eksport formatlari va ularning qo&#39;llanilishi&quot;">​</a></h3><p>Tayyor wireframeni boshqalar bilan bo&#39;lishish uchun to&#39;g&#39;ri format tanlash zarur:</p><ul><li><strong>PNG (Raster rasm):</strong> Taqdimotlar, messenjerlarda mijozga tezkor ko&#39;rsatish va Figmaga fon rasmi sifatida kiritish uchun qulay.</li><li><strong>SVG (Vektor grafikasi):</strong> Vektorli format bo&#39;lib, o&#39;lchami o&#39;zgarganda sifati buzilmaydi, Figmada har bir chiziqni alohida tahrirlash imkonini beradi.</li><li><strong>PDF (Hujjat):</strong> Butun loyihani ko&#39;p sahifali rasmiy texnik hujjat (Specification) sifatida chop etish va mijozga tasdiqlatish uchun eng yaxshi format.</li></ul><h3 id="_2-3-wireframeni-figmaga-o-tkazish-ui-dizaynga-ko-prik" tabindex="-1">2.3. Wireframeni Figmaga o&#39;tkazish (UI Dizaynga ko&#39;prik) <a class="header-anchor" href="#_2-3-wireframeni-figmaga-o-tkazish-ui-dizaynga-ko-prik" aria-label="Permalink to &quot;2.3. Wireframeni Figmaga o&#39;tkazish (UI Dizaynga ko&#39;prik)&quot;">​</a></h3><p>Wireframing — bu loyihaning skeleti. Keyingi bosqich — <strong>UI Dizayn (User Interface)</strong> bo&#39;lib, unda ranglar, shriftlar, rasmlar va komponentlar qo&#39;shiladi.</p><p>Ko&#39;chirish bosqichlari:</p><ol><li>Axure RP yoki Balsamiq&#39;dan wireframe PNG yoki SVG formatida eksport qilinadi.</li><li>Figma ochiladi va yangi loyiha (Design File) yaratiladi.</li><li>Eksport qilingan wireframe Figmaga <code>Drag &amp; Drop</code> (sudrab tashlash) yoki <code>File &amp;rarr; Place Image</code> orqali yuklanadi.</li><li>Wireframe qatlami (Layer) shaffofligi 30-40% ga tushiriladi va qulflanadi (<code>Lock</code>).</li><li>Uning ustidan yangi Frame chizilib, haqiqiy UI elementlari (Auto Layout, Komponentlar, Ranglar) bilan boyitiladi.</li></ol><hr>`,13))]),i("div",f,[i("h2",y,[l(t,{name:"file-text"}),a[6]||(a[6]=r(" 3. Amaliy mashg'ulot ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-amaliy-mashg-ulot","aria-label":`Permalink to "<Icon name="file-text" /> 3. Amaliy mashg'ulot"`},"​",-1))]),a[8]||(a[8]=n('<h3 id="_1-mashq-«online-books»-bosh-sahifasiga-annotatsiya-tuzish" tabindex="-1">1-mashq. «Online books» bosh sahifasiga annotatsiya tuzish <a class="header-anchor" href="#_1-mashq-«online-books»-bosh-sahifasiga-annotatsiya-tuzish" aria-label="Permalink to &quot;1-mashq. «Online books» bosh sahifasiga annotatsiya tuzish&quot;">​</a></h3><p><strong>Vazifa:</strong> Bosh sahifadagi Header, Banner, Kitoblar ro&#39;yxati va Footer bloklariga 4 ta raqamli marker qo&#39;yib, har biri uchun texnik izoh yozing.</p><p><strong>Yechim:</strong></p><ul><li><strong>Marker 1 (Header/Search):</strong> «Foydalanuvchi qidiruvga kitob nomi yoki muallifni yozganda real vaqtda mos natijalar ro&#39;yxati chiqadi».</li><li><strong>Marker 2 (Aksiya banneri):</strong> «Banner har 5 soniyada avtomatik keyingi aksiyaga o&#39;tadi, sichqoncha ustiga borganda to&#39;xtaydi».</li><li><strong>Marker 3 (Ommabop kitoblar):</strong> «Bir qatorda 4 ta kitob kartasi joylashadi, &#39;Barchasi&#39; bosilganda to&#39;liq katalogga yo&#39;naltiriladi».</li><li><strong>Marker 4 (Footer):</strong> «Sayt navigatsiyasi, ijtimoiy tarmoqlar va mualliflik huquqi ma&#39;lumotlari keltiriladi».</li></ul><hr><h3 id="_2-mashq-figmaga-eksport-va-referens-qatlamini-yaratish" tabindex="-1">2-mashq. Figmaga eksport va referens qatlamini yaratish <a class="header-anchor" href="#_2-mashq-figmaga-eksport-va-referens-qatlamini-yaratish" aria-label="Permalink to &quot;2-mashq. Figmaga eksport va referens qatlamini yaratish&quot;">​</a></h3><p><strong>Vazifa:</strong> Tayyorlangan wireframeni PNG formatida eksport qilib, Figma ish maydoniga joylashtiring va ustiga yangi UI Frame chizing.</p><p><strong>Yechim:</strong></p><ol><li>Axure RP da <code>File &amp;rarr; Export &amp;rarr; Export Pages to Image...</code> (Balsamiq&#39;da <code>Project &amp;rarr; Export &amp;rarr; Current Wireframe to PNG</code>).</li><li>Figma veb-versiyasi yoki dasturida <code>Desktop 1440</code> o&#39;lchamli Frame ochiladi.</li><li>PNG rasm Frame ichiga joylashtiriladi.</li><li>Layer qismida uning Opacity qiymati <code>40%</code> qilinadi va <code>Lock</code> belgisi bosiladi.</li><li>Dizayner endi ushbu karkas ustidan aniq piksellar va ranglar bilan yakuniy UI dizaynni chizishga tayyor.</li></ol><hr>',10))]),i("div",p,[i("h2",b,[l(t,{name:"file-text"}),a[9]||(a[9]=r(" 4. Tezkor savollar (Checklist) ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-tezkor-savollar-checklist","aria-label":'Permalink to "<Icon name="file-text" /> 4. Tezkor savollar (Checklist)"'},"​",-1))]),a[11]||(a[11]=n("<ol><li>Annotated wireframe (Izohli simli ramka) nima uchun kerak? <ul><li><strong>Javob:</strong> Dasturchilar va buyurtmachiga interfeys qanday ishlashi, cheklovlar va funksional qoidalarni aniq tushuntirish uchun.</li></ul></li><li>Wireframeni eksport qilishda qaysi 3 ta format eng ko&#39;p qo&#39;llaniladi? <ul><li><strong>Javob:</strong> PNG (rasm), SVG (vektor) va PDF (hujjat).</li></ul></li><li>Figmaga wireframeni import qilgandan so&#39;ng nega uning shaffofligi (Opacity) kamaytiriladi va qulflanadi? <ul><li><strong>Javob:</strong> U shunchaki asos (reference) vazifasini bajaradi; ustidan yangi toza UI elementlarini chizishda xalaqit bermasligi va siljib ketmasligi uchun.</li></ul></li><li>Wireframe bosqichidan UI dizayn bosqichiga o&#39;tganda nimalar qo&#39;shiladi? <ul><li><strong>Javob:</strong> Haqiqiy ranglar, professional tipografiya, fotosuratlar, piktogrammalar (ikonlar) va dizayn tizimi (UI Kit).</li></ul></li><li>1.3-mavzu davomida biz qanday asosiy dasturlarni o&#39;rgandik? <ul><li><strong>Javob:</strong> Balsamiq (tezkor Low-fi eskizlar) va Axure RP (chuqur interaktiv va mantiqiy prototiplar).</li></ul></li></ol>",1))])])}const F=s(m,[["render",c]]);export{I as __pageData,F as default};
